import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.k9nOhppk.js";const u=JSON.parse('{"title":"Lexical structure","description":"","frontmatter":{"title":"Lexical structure"},"headers":[],"relativePath":"reference/language/lexical-structure.md","filePath":"reference/language/lexical-structure.md","lastUpdated":1791864160000}'),s={name:"reference/language/lexical-structure.md"};function n(c,e,i,r,l,h){return t(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="lexical-structure" tabindex="-1">Lexical structure <a class="header-anchor" href="#lexical-structure" aria-label="Permalink to &quot;Lexical structure&quot;">​</a></h1><p>Source files are UTF-8. Names and keywords are ASCII; strings and comments may contain any text.</p><ul><li><p><strong>Comments:</strong> <code>#</code> to the end of the line. A comment that starts with <code>##</code> is a doc comment: it documents the declaration, member, field or variant directly below it. A blank line or a plain comment in between detaches it. <code>eye doc</code> publishes doc comments, editors show them on hover and in completion, and a model call uses them to describe that part of the schema (<a href="/reference/language/ai-models-and-agents">section 19</a>).</p><ul><li>A doc comment is Markdown. Its first sentence is the summary that indexes, completion lists and hover headers show, so it should say what the thing is or does on its own.</li><li><code>[Name]</code>, <code>[Type.member]</code> and <code>[module.Name]</code> link to the declaration they name. <code>eye doc</code> turns them into links and fails on a link that names nothing, so docs can&#39;t point at code that was renamed or removed.</li><li>A <code>##</code> block at the top of a file, separated from the first declaration by a blank line, documents the module. Plain <code>#</code> comments are never published: use them for notes to whoever maintains the code.</li></ul></li><li><p><strong>Names:</strong> a letter or <code>_</code>, then letters, digits and <code>_</code>. A name that starts with an upper-case letter names a type, variant, entity or contract (<code>World</code>, <code>Some</code>, <code>Notify</code>); any other name is a value, function, field or module (<code>world</code>, <code>markAsleep</code>, <code>zeropod</code>). Names can no longer end in <code>!</code> or <code>?</code> (Eyelang 1 allowed <code>update!</code> and <code>ok?</code>): <code>!</code> now marks waiting calls and <code>?</code> propagates errors.</p></li><li><p><strong>Literals:</strong></p><table tabindex="0"><thead><tr><th>Kind</th><th>Examples</th></tr></thead><tbody><tr><td>Int (arbitrary precision)</td><td><code>0</code>, <code>42</code>, <code>1_000_000</code>, <code>0xC2</code>, <code>0b1010_0101</code></td></tr><tr><td>Float (64-bit IEEE 754, but NaN equals itself: <a href="/reference/language/errors-result-only">section 10</a>)</td><td><code>1.5</code>, <code>0.25</code>, <code>6.02e23</code></td></tr><tr><td>String, with interpolation</td><td><code>&quot;hello&quot;</code>, <code>&quot;ireland-{day}&quot;</code>, <code>&quot;\\{literal brace}&quot;</code></td></tr><tr><td>Bool</td><td><code>true</code>, <code>false</code></td></tr><tr><td>Char</td><td><code>&#39;a&#39;</code>, <code>&#39;\\n&#39;</code>, <code>&#39;\\u{1F600}&#39;</code></td></tr><tr><td>Unit</td><td><code>()</code></td></tr><tr><td>Duration</td><td><code>500 ms</code>, <code>20 min</code>, <code>3 h</code>, <code>2 days</code>, <code>1.5 h</code></td></tr><tr><td>Size</td><td><code>512 B</code>, <code>64 KiB</code>, <code>64 MiB</code>, <code>6 GiB</code></td></tr><tr><td>Time of day</td><td><code>07:40</code>, <code>23:59:30</code></td></tr><tr><td>Date</td><td><code>2026-10-10</code></td></tr><tr><td>Instant</td><td><code>2026-10-10 07:40 in &quot;Europe/Dublin&quot;</code>, <code>2026-10-10 07:40 in dublin</code></td></tr><tr><td>Next time of day in a zone</td><td><code>07:45 in &quot;Europe/Dublin&quot;</code>, <code>07:45 in dublin</code></td></tr></tbody></table><p>A number followed by a unit name (<code>ms</code>, <code>s</code>, <code>min</code>, <code>h</code>, <code>day</code>, <code>days</code>, <code>week</code>, <code>weeks</code>, <code>B</code>, <code>KiB</code>, <code>MiB</code>, <code>GiB</code>) is a Duration or Size. A date or time of day is written without spaces; <code>2026 - 10 - 10</code> is still subtraction. Times are two digits each: <code>7:40</code> is not a time. A literal names a real date or time, or is an error at it: hours go from <code>00</code> to <code>23</code>, minutes and seconds from <code>00</code> to <code>59</code>, months from <code>01</code> to <code>12</code>, and the day must exist in its month, so <code>25:00</code>, <code>12:60</code> and <code>2026-02-30</code> are errors. Midnight is <code>00:00</code>; <code>24:00</code> is not a time. The zone after <code>in</code> is a zone&#39;s name, or a name for a <code>Zone</code> value: <code>dublin</code> after <code>pub let dublin: Zone = &quot;Europe/Dublin&quot;</code>.</p><p>An integer may be written in hexadecimal after <code>0x</code> (<code>0xC2</code>, <code>0xFFFF_FFFF</code>) or in binary after <code>0b</code> (<code>0b1010_0101</code>), with <code>_</code> between digits as in decimal, and is an <code>Int</code>, or any fixed-width type where one is expected: <code>let lead: Byte = 0xC2</code>. The prefix is lower case; hex digits may be either, and <code>eye fmt</code> writes them upper case, keeping the base the author wrote, so a byte range stays <code>0xC2..=0xDF</code> and a mask stays binary. A leading <code>0</code> doesn&#39;t make a number octal: <code>007</code> is 7. <code>0x</code> with no hex digit after it is an error that says so.</p></li><li><p><strong>Characters:</strong> <code>&#39;a&#39;</code> is a <code>Char</code>, one Unicode scalar value, with the escapes of strings plus <code>\\&#39;</code>. Where a <code>Byte</code> is expected, an ASCII character literal is a <code>Byte</code>: <code>src[i] == Some(&#39;&quot;&#39;)</code> (<a href="/reference/language/values-and-types">section 5</a>).</p></li><li><p><strong>Strings:</strong> a string&#39;s text stays on one line, though an interpolated expression may break across lines. The escapes are <code>\\n</code>, <code>\\r</code>, <code>\\t</code>, <code>\\0</code>, <code>\\\\</code>, <code>\\&quot;</code>, <code>\\{</code>, <code>\\}</code> and <code>\\u{1F600}</code>. <code>{expression}</code> interpolates a value that has <code>Show</code>.</p><p>A <strong>multi-line string</strong> starts with <code>&quot;&quot;&quot;</code> at the end of a line and ends at a <code>&quot;&quot;&quot;</code> with only spaces before it on its line. Those spaces are the margin: every line starts with it, or is blank, and loses it, and the line breaks after the opening <code>&quot;&quot;&quot;</code> and before the closing line aren&#39;t part of the string. One or two quotes inside are text; escapes and interpolation work as in other strings.</p><div class="language-eye vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">eye</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> prompt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  You write a morning briefing for {reader}.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    - this line keeps two spaces</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  Say &quot;Nothing new.&quot; when nothing matters.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;&quot;&quot;</span></span></code></pre></div></li><li><p><strong>Keywords.</strong> These are reserved and are never names: <code>let var mut fn pub return if else match for in while break continue true false _</code>. Every other keyword is a keyword only where the grammar expects it, and an ordinary name everywhere else, so <code>state</code>, <code>view</code>, <code>type</code> and <code>test</code> work as variable and field names:</p><ul><li>at the start of a declaration: <code>import type opaque trait impl entity job view contract test extern</code>;</li><li>inside declarations: <code>state</code> and <code>migrate … from</code> in entities; <code>command</code>, <code>query</code>, <code>event</code> and <code>on</code> in contracts; <code>uses</code> and <code>where</code> after a signature;</li><li><code>with</code> at the start of a statement and inside a record update, <code>dyn</code> at the start of a type, and the unit names after a number.</li></ul><p>A contextual keyword is read as a keyword wherever one is allowed, so a variable named <code>with</code> can&#39;t begin a statement. <code>in</code> and <code>for</code> may also be argument labels: <code>daily(07:40, in: zone)</code>.</p></li><li><p><strong>Attributes:</strong> <code>@name</code> or <code>@name(args)</code> before a declaration or member.</p></li><li><p><strong>One style.</strong> <code>eye fmt</code> keeps the line breaks you chose and fixes everything else: two spaces of indentation, spacing around operators and after commas and colons, <code>;</code> turned into line breaks, trailing commas in lists that end on their own line, aligned trailing comments, and hex digits in upper case (<code>0xc2</code> is written <code>0xC2</code>). It has no options. Formatting a program&#39;s directory also writes public functions&#39; <code>uses</code> clauses (<a href="/reference/language/effects-and-signatures">section 12</a>).</p></li><li><p><strong>Newlines end statements.</strong> A line break ends a statement, declaration, member or match arm wherever one could end. It doesn&#39;t when the next line (ignoring blank and comment lines) starts with a binary operator, <code>.</code>, <code>?</code>, <code>,</code>, <code>:</code>, <code>=</code>, <code>-&gt;</code> or <code>else</code>; <code>-</code> and <code>!</code> continue only as <code>-&gt;</code> and <code>!=</code>, since <code>-x</code> and <code>!x</code> can start a statement. Inside <code>(…)</code>, <code>[…]</code> and record or map braces no statement can end, so line breaks there are ordinary spaces (until a lambda&#39;s block starts a new list of statements). <code>;</code> separates statements on one line.</p><div class="language-eye vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">eye</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ready </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> worlds</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> filter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> w: w.phase </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Running</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># continues: the line starts with |&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> size</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> next </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(b)                                        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># a new statement, not the call a(b)</span></span></code></pre></div></li><li><p><strong>Braces.</strong> Braces hold blocks of statements and data; layout is free and indentation means nothing. A branch that is one expression needs no braces: <code>if n &lt; 2 then n else fib(n - 1)</code>, <code>Some(v) =&gt; v</code>, <code>fn x: x + 1</code>, <code>fn double(n) = n * 2</code>.</p><p><code>{</code> opens a block after <code>if …</code> (without <code>then</code>), <code>else</code> (after a block), <code>for … in …</code>, <code>while</code>, <code>let … else</code>, a function or job signature, <code>test &quot;…&quot;</code> and a lambda&#39;s parameters. In any other expression position it starts a record (<code>{ name: &quot;Ann&quot; }</code>), a map (<code>{ &quot;a&quot;: 1 }</code>), an update (<code>{ user with age: 4 }</code>) or the empty <code>{}</code>. After a match arm&#39;s <code>=&gt;</code>, <code>{</code> opens a block unless <code>name:</code>, <code>name,</code> or <code>name with</code> follows, since only a record starts that way: <code>Some(u) =&gt; { u with seen: true }</code> returns a record, <code>None =&gt; {}</code> is an empty block, and a record with one shorthand field, <code>{ u }</code>, or a map needs parentheses there: <code>=&gt; ({ u })</code>.</p></li><li><p><strong>Waiting calls:</strong> in <code>f!(x)</code> the <code>!</code> and <code>(</code> follow the callee with no spaces. <code>x != y</code> and <code>!x</code> are the usual operators.</p></li></ul>`,3)])])}const m=o(s,[["render",n]]);export{u as __pageData,m as default};
